<?php require __DIR__.'/_start.php'; ?><section class="customer-card"><h2>Size ait gelişmeler</h2><?php if(!$notifications): ?><p class="empty-state">Henüz bildiriminiz yok.</p><?php endif ?><?php foreach($notifications as $notification): ?><article class="customer-notification <?= $notification['read_at']?'':'is-unread' ?>"><div><p><?= e($notification['message']) ?></p><small><?= e(date('d.m.Y H:i',strtotime($notification['created_at']))) ?> · <?= $notification['read_at']?'Okundu':'Okunmadı' ?></small><?php if($notification['appointment_id']): ?><a href="<?= e(url('customer/appointments/detail?id='.$notification['appointment_id'])) ?>">Randevu detayı</a><?php endif ?></div><?php if(!$notification['read_at']): ?><form method="post" action="<?= e(url('customer/notifications/read')) ?>"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$notification['id'] ?>"><button type="submit" class="btn btn-sm btn-outline-dark">Okundu işaretle</button></form><?php endif ?></article><?php endforeach ?><p class="muted mt-3">En son 200 bildirim gösterilir. Bildirim tercihinizi profilinizden değiştirebilirsiniz.</p></section><?php require __DIR__.'/_end.php'; ?>
